<template>
  <div
    class="table-resize-handle absolute bottom-0 right-0 z-10 flex size-6 cursor-ns-resize items-center justify-center text-muted-foreground hover:text-foreground"
    role="separator"
    aria-orientation="horizontal"
    :aria-label="$t('resize_table_height')"
    :title="$t('resize_table_height')"
    @pointerdown="onPointerDown"
  >
    <Icon icon="mdi:resize-bottom-right" class="size-5" />
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { Icon } from '@iconify/vue';
import { computeResizeHeight } from 'src/utils/tableResizeHeight';

export default defineComponent({
  name: 'TableResizeHandle',
  components: { Icon },
  props: {
    targetSelector: {
      type: String,
      default: '.q-table__middle',
    },
    minHeight: {
      type: Number,
      default: 120,
    },
    maxHeight: {
      type: Number,
      default: 0,
    },
  },
  data() {
    return {
      startY: 0,
      startHeight: 0,
    };
  },
  beforeUnmount() {
    this.stopDragging();
  },
  methods: {
    scrollArea(): HTMLElement | null {
      const wrapper = (this.$el as HTMLElement).closest('.resizable-table');
      return wrapper ? wrapper.querySelector(this.targetSelector) : null;
    },
    resolvedMaxHeight(): number {
      return this.maxHeight > 0 ? this.maxHeight : window.innerHeight * 0.9;
    },
    onPointerDown(event: PointerEvent) {
      const area = this.scrollArea();
      if (!area) {
        return;
      }
      this.startY = event.clientY;
      this.startHeight = area.getBoundingClientRect().height;
      (event.target as HTMLElement).setPointerCapture?.(event.pointerId);
      document.addEventListener('pointermove', this.onPointerMove);
      document.addEventListener('pointerup', this.stopDragging);
      event.preventDefault();
    },
    onPointerMove(event: PointerEvent) {
      const area = this.scrollArea();
      if (!area) {
        return;
      }
      const height = computeResizeHeight(
        event.clientY,
        this.startY,
        this.startHeight,
        this.minHeight,
        this.resolvedMaxHeight(),
      );
      area.style.maxHeight = 'none';
      area.style.height = `${height}px`;
    },
    stopDragging() {
      document.removeEventListener('pointermove', this.onPointerMove);
      document.removeEventListener('pointerup', this.stopDragging);
    },
  },
});
</script>
