<template>
  <div class="full-width">
    <div
      v-if="formBuilderConfigModel[fieldName].displayLabelOnLeft"
      :style="'width:' + formBuilderConfigModel[fieldName].labelWidth + '%'"
      class="display-block"
    >
      <div :class="fieldName" class="full-width">
        <span>{{
          getFieldLabel(
            formBuilderConfigModel[fieldName],
            '',
          )
        }}</span>
        <q-icon
          v-if="isFieldHidden()"
          name="visibility_off"
          size="xs"
          color="grey-6"
          class="q-ml-xs"
        >
          <q-tooltip>{{ $t('field_is_hidden') }}</q-tooltip>
        </q-icon>
        <ExtractionSourceBadge
          :extraction-method="formBuilderModel[fieldName]?.extraction_method"
        />
        <span v-if="false" class="text-red"> * </span>
      </div>
    </div>

    <div
      :style="
        'width:' + getInputFieldWidth(formBuilderConfigModel[fieldName]) + '%'
      "
      class="display-block"
    >
      <div
        class="col-sm-12 col-md-12 col-lg-12 display-flex"
        v-if="!formBuilderConfigModel[fieldName].displayLabelOnLeft"
      >
        <div class="ellipsify full-width" :class="fieldName">
          <span>{{
            getFieldLabel(
              formBuilderConfigModel[fieldName],
              '',
            )
          }}</span>
          <q-icon
            v-if="isFieldHidden()"
            name="visibility_off"
            size="xs"
            color="grey-6"
            class="q-ml-xs"
          >
            <q-tooltip>{{ $t('field_is_hidden') }}</q-tooltip>
          </q-icon>
          <ExtractionSourceBadge
            :extraction-method="formBuilderModel[fieldName]?.extraction_method"
          />
          <span v-if="false" class="text-red"> * </span>

          <q-tooltip>{{
            getFieldLabel(
              formBuilderConfigModel[fieldName],
              '',
            )
          }}</q-tooltip>
        </div>
      </div>

      <div
        :id="fieldName"
        :child_type="
          formBuilderConfigModel[fieldName].is_textarea ? 'textarea' : 'input'
        "
        class="col-sm-12 col-md-12 col-lg-12 autocomplete"
        :class="
          formBuilderConfigModel[fieldName].is_textarea
            ? ' '
            : ' input-text-28px'
        "
        role="combobox"
        aria-autocomplete="list"
        aria-controls="suggestions"
        aria-expanded="false"
      >
        <q-select
          outlined
          clearable
          use-input
          hide-selected
          fill-input
          hide-dropdown-icon
          :data-test="'field-input-' + fieldName"
          :data-name="fieldName"
          :data-field-name="formBuilderConfigModel[fieldName].field_name"
          :options="filteredList"
          :disable="
            isReadOnly ||
            formBuilderConfigModel[fieldName].is_readonly ||
            (lookup_loading_fields.hasOwnProperty(fieldName) &&
              lookup_loading_fields[fieldName].lookup_loading)
          "
          :class="
            'full-width input-field ellipsify autocomplete-field ' +
            formBuilderConfigModel[fieldName].field_name +
            '_input ' +
            formBuilderConfigModel[fieldName].color +
            ' ' +
            (formBuilderModel[fieldName].input_error ? ' invalid-input ' : '') +
            formBuilderModel[fieldName].input_error
          "
          @click="
            (e: any) => {
              inputFieldClicked(e, fieldName);
            }
          "
          @update:model-value="
            (new_value: any) => {
              changeEventHandler(new_value);
            }
          "
          v-model="formBuilderModel[fieldName].formatted_value"
          emit-value
          map-options
          @filter="filterlistEvent"
        >
          <template v-slot:append>
            <template v-if="lookup_loading_fields.hasOwnProperty(fieldName)">
              <div v-if="lookup_loading_fields[fieldName].lookup_loading">
                <q-spinner-ios color="primary" size="0.86em" />
              </div>

              <q-icon
                v-if="lookup_loading_fields[fieldName].lookup_found == true"
                flat
                dense
                name="check_circle"
                size="18px"
                class="cursor-pointer text-light-green-8"
                tabindex="0"
              >
                <q-tooltip>{{ $t('lookup_record_found') }}</q-tooltip>
              </q-icon>

              <q-icon
                v-if="lookup_loading_fields[fieldName].lookup_found == false"
                flat
                dense
                name="warning"
                size="18px"
                class="cursor-pointer text-orange"
                tabindex="0"
              >
                <q-tooltip>{{ $t('no_lookup_record_found') }}</q-tooltip>
              </q-icon>
            </template>

            <div
              class="cursor-pointer fuzzy-field flex items-center"
              v-if="lookup_configurations.has(fieldName)"
              @click="
                $event.stopPropagation();
                $event.preventDefault();
                $emit('applyFuzzySearch', formBuilderModel[fieldName]);
              "
            >
              <Icon icon="mdi:text-search" width="18" height="18" />
            </div>

            <InfoPanel :fieldName="fieldName" v-if="isExtraInfo(fieldName)" />

            <q-badge
              v-if="isFormBuilderMode && showTabIndex"
              color="orange"
              text-color="black"
              :label="formBuilderConfigModel[fieldName].tabIndex"
            />
          </template>
          <q-tooltip v-if="formBuilderModel[fieldName].formatted_value && getToolTip()">
            {{ getToolTip() }}
          </q-tooltip>
        </q-select>
      </div>
    </div>
  </div>

  <q-dialog
    v-model="confirmAccountingDataRest"
    persistent
    @keydown.esc="resetChange()"
  >
    <q-card>
      <q-card-section class="row items-center">
        <q-avatar icon="info" color="primary" text-color="white" />
        <span class="q-ml-sm">
          {{
            $t(
              'BY_CONFIRMING_THIS_CHANGE_YOU_WILL_LOSE_ACCOUNTING_DATA',
            )
          }}
        </span>
      </q-card-section>

      <q-card-actions align="right">
        <q-btn
          flat
          :label="$t('cancel')"
          color="primary"
          v-close-popup
          @click="resetChange()"
        />
        <q-btn
          flat
          :label="$t('proceed')"
          color="primary"
          v-close-popup
          @click="removeAccountingDataAndProceed()"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import intUtils from 'src/utils/int';
import { defineComponent, ref } from 'vue';

import displayFieldLabel from 'src/utils/displayFieldLabel';
import validation_mixin from 'src/validatior/validation_mixin';
import { CONSTANTS } from 'src/constants';
import formBuilderHelper from 'src/formBuilder/utils/formBuilderHelper';
import InfoPanel from 'src/formBuilder/form_elements/components/InfoPanel.vue';
import ExtractionSourceBadge from 'src/components/ExtractionSourceBadge.vue';
import {
  useFormBuilderStore,
  useFieldValuesSettingsStore,
  useLookupFunctionStore,
  useDocumentStore,
  useUserStore,
} from 'src/store/main';

export default defineComponent({
  name: 'EnumInput',
  components: {
    
    InfoPanel,
    ExtractionSourceBadge,
  },
  props: {
    currentField: {
      type: Object,
      default: new Object(),
    },
    fieldName: {
      type: String,
      default: '',
    },
    isReadOnly: {
      type: Boolean,
      default: false,
    },
    groupIndex: {
      type: Number,
      default: 0,
    },
    itemIndex: {
      type: Number,
      default: 0,
    },
  },
  emits: [
    'inputClicked',
    'inputValueChanges',
    'updateModel',
    'applyFuzzySearch',
    'itemAdded',
    'removeField',
    'markTableColumns',
  ],
  mixins: [displayFieldLabel, formBuilderHelper, validation_mixin, intUtils],
  data() {
    return {
      modelVaule: ref(),
      confirmAccountingDataRest: ref(false),
    };
  },

  beforeMount: function () {
    if (this.isFormBuilderMode) {
      this.$emit('updateModel', this.currentField);
    }
  },
  mounted: function () {
    this.modelVaule = this.formBuilderModel[this.fieldName].formatted_value;
    this.options = this.getListOfValuesAsSelectList(
      this.formBuilderConfigModel[this.fieldName].list_of_values,
    );
    this.getSubOrgAndFilterLov();
  },
  methods: {
    resetChange() {
      this.confirmAccountingDataRest = false;
      this.formBuilderModel[this.fieldName].formatted_value = this.modelVaule;
    },
    inputFieldClicked(event: any, fieldName: string) {
      if (!this.isFormBuilderMode) {
        return;
      }
      event.stopPropagation();
      this.$emit('inputClicked', fieldName);
    },
    changeEventHandler(new_value: any) {
      if (this.shouldConfirmAccountingReset(this.fieldName)) {
        this.confirmAccountingDataRest = true;
        return;
      }
      this.proceedChange(new_value);
    },
    proceedChange(new_value: any) {
      if (new_value && new_value.includes('\u200B')) {
        new_value = new_value.replace(/\u200B/g, '');
      }
      this.modelVaule = new_value;
      this.formBuilderModel[this.fieldName].formatted_value = new_value;
      this.formBuilderModel[this.fieldName].value = new_value;
      this.formBuilderModel[this.fieldName].input_error = '';
      this.formBuilderConfigModel[this.fieldName].color =
        CONSTANTS.success_border_left;
      this.$emit('inputValueChanges', this.fieldName, 'input');
    },
    removeAccountingDataAndProceed() {
      this.removeAccountingData();
      this.proceedChange(this.formBuilderModel[this.fieldName].formatted_value);
    },
    filterlistEvent(val: string, update: any, abort: any) {
      if (!val) {
        update(() => {
          this.filteredList = this.options;
        });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.filteredList = this.options.filter(
          (v: any) => v.label.toLowerCase().indexOf(needle) > -1,
        );
      });
    },
    getToolTip() {
      const value = this.formBuilderModel[this.fieldName].formatted_value;

      const matchingObject = this.options.find(
        (item: any) => item.value === value,
      );
      return matchingObject ? String(matchingObject.label) : '';
    },

    async getSubOrgAndFilterLov() {
      const sub_org_id = await this.getSubOrgId();
      //Filter out other values that have differnt sub-org ID
      const filteredOptions = this.options.filter(
        (lov: { sub_org_id: string | null }) =>
          lov.sub_org_id === null || lov.sub_org_id == sub_org_id,
      );
      //Set filtered options to both options and filteredList for rendering
      this.options = filteredOptions;
      this.filteredList = filteredOptions;
    },

    isFieldHidden() {
      // Check if field is hidden in Field Settings (defaultFields)
      const field = this.defaultFields.find(
        (f: any) => f.field_name === this.fieldName || f.name === this.fieldName
      );
      return field ? (field.isHidden === true) : false;
    },
  },
  setup() {
    const form_builder_store = useFormBuilderStore();
    const {
      formBuilderModel,
      isFormBuilderMode,
      formBuilderConfigModel,
      showTabIndex,
      defaultFields,
    } = storeToRefs(form_builder_store);
    const { isExtraInfo } = form_builder_store;

    const field_values_setting_store = useFieldValuesSettingsStore();
    const { getListOfValuesAsSelectList } = field_values_setting_store;

    const lookup_function_store = useLookupFunctionStore();
    const { lookup_loading_fields } = storeToRefs(lookup_function_store);

    const doc_store = useDocumentStore();
    const { record, lookup_configurations } = storeToRefs(doc_store);
    const { removeAccountingData, shouldConfirmAccountingReset } = doc_store;

    const user_store = useUserStore();
    const { getSubOrgId } = user_store;

    return {
      record,
      showTabIndex,
      formBuilderModel,
      isFormBuilderMode,
      lookup_loading_fields,
      lookup_configurations,
      formBuilderConfigModel,
      defaultFields,

      isExtraInfo,
      removeAccountingData,
      shouldConfirmAccountingReset,
      getListOfValuesAsSelectList,

      options: ref([] as any),
      filteredList: ref([] as any),
      getSubOrgId,
    };
  },
});
</script>
<style lang="scss" scoped>
.autocomplete {
  position: relative;
}

:deep(.autocomplete-field .q-field__native) {
  padding: unset !important;
}
</style>
